import{_ as t,o as a,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0043 — Recherche dans le contenu des documents : extraction native dans le Core, Apache Tika livré inactif","description":"Extrait de docs/adr/0043-extraction-documentaire-native-et-tika.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0043 — Recherche dans le contenu des documents : extraction native dans le Core, Apache Tika livré inactif","description":"Extrait de docs/adr/0043-extraction-documentaire-native-et-tika.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0043-extraction-documentaire-native-et-tika.md","filePath":"developpeurs/adr/0043-extraction-documentaire-native-et-tika.md"}'),o={name:"developpeurs/adr/0043-extraction-documentaire-native-et-tika.md"};function s(r,e,d,c,u,l){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0043--recherche-dans-le-contenu-des-documents--extraction-native-dans-le-core-apache-tika-livré-inactif" tabindex="-1">ADR-0043 — Recherche dans le contenu des documents : extraction native dans le Core, Apache Tika livré inactif <a class="header-anchor" href="#adr-0043--recherche-dans-le-contenu-des-documents--extraction-native-dans-le-core-apache-tika-livré-inactif" aria-label="Permalink to &quot;ADR-0043 — Recherche dans le contenu des documents : extraction native dans le Core, Apache Tika livré inactif {#adr-0043--recherche-dans-le-contenu-des-documents--extraction-native-dans-le-core-apache-tika-livré-inactif}&quot;">​</a></h1><p><strong>Date :</strong> 23 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §10.1, §14.4, §16.2 ; clôt l&#39;action « extraction documentaire » de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0042-mediatheque-branchements">ADR-0042</a> ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a> (adaptateur livré inactif) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> (un média est public par nature)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Depuis l&#39;Epic E3, l&#39;index lexical (<code>search_index</code>) est conçu pour accueillir des documents : <code>source_type=&#39;document&#39;</code>, <code>document_id</code>, <code>extracted_text</code>. Rien ne le remplissait. Le seul chemin d&#39;extraction passait par le socle IA (tâche <code>document_extraction</code>, <code>OcrPort</code>), et aucun fournisseur réel n&#39;y était branché.</p><p>L&#39;ADR-0042 avait reporté ce chantier pour trois raisons :</p><ul><li>il n&#39;y avait pas de moteur ;</li><li>il y avait une dépendance à trancher ;</li><li>l&#39;index unique de <code>search_index.document_id</code> interdisait d&#39;indexer un document dans plus d&#39;un site, alors que la médiathèque appartient à l&#39;organisation et que toute recherche est bornée à un site.</li></ul><p>La plupart des documents d&#39;une collectivité (délibérations, arrêtés, comptes rendus) sont des PDF produits depuis un traitement de texte : ils portent déjà leur texte. Seuls les scans demandent de l&#39;OCR.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Deux temps</strong> (décision du Product Owner).</p><ul><li><strong>Dans le Core, sans service à déployer</strong> : <code>pypdf</code> pour les PDF, lecture directe du txt et du csv (UTF-8, puis windows-1252, l&#39;encodage des exports de tableur français).</li><li><strong>Apache Tika</strong>, adaptateur facultatif <strong>livré inactif</strong>, pour les PDF scannés (OCR par Tesseract, variante d&#39;image <code>-full</code>) et les fichiers Office (doc, docx, xls, xlsx, ppt, pptx, odt, ods, odp).</li></ul><p><strong>2. Tika n&#39;est pas de l&#39;IA.</strong> Il ne passe ni par <code>OcrPort</code> ni par le <code>ProviderManager</code> : aucune politique IA par organisation, aucun budget, aucune ligne dans <code>ai_jobs</code>.</p><ul><li>Un port d&#39;extraction à part, <code>DocumentTextExtractor</code> (<code>app/media/extraction.py</code>), porte une chaîne : l&#39;extracteur natif d&#39;abord, le moteur facultatif ensuite.</li><li>Un résultat « rien trouvé, mais un moteur plus riche pourrait » (un PDF sans couche texte) passe au suivant.</li><li>Le chemin IA existant reste en place, à côté.</li></ul><p><strong>3. Tous les documents sont indexés, sauf exclusion</strong> (décision du Product Owner). Un média est public par nature (ADR-0041, §10). La colonne <code>media_assets.searchable</code> (vraie par défaut) porte la case « Exclure ce document de la recherche du site ». Un média exclu n&#39;a <strong>aucune</strong> ligne d&#39;index : l&#39;exclusion supprime les lignes, elle ne les masque pas.</p><p><strong>4. Une ligne d&#39;index par site.</strong> La médiathèque est celle de l&#39;organisation : un document apparaît dans la recherche de chacun de ses sites.</p><ul><li>L&#39;index unique partiel <code>document_id</code> devient <code>(document_id, site_id)</code>.</li><li><code>document_id</code> reçoit enfin sa clé étrangère vers <code>media_assets</code> (<code>ON DELETE CASCADE</code>), annoncée depuis l&#39;Epic E3 (migration <code>0035</code>).</li><li>La migration supprime les lignes qui ne désignaient aucun média de leur organisation. Ce sont des données dérivées sans source, et une ligne pointant le média d&#39;une autre organisation serait une fuite que la clé ne voit pas.</li><li>Un site créé après coup retrouve les documents au passage suivant, <strong>sans ré-extraction</strong> : le texte est recopié d&#39;une ligne existante.</li><li>Chaque ligne prend la langue par défaut de son site.</li><li>Un résultat de recherche de document porte <code>document_path</code>, le chemin public du fichier.</li></ul><p><strong>5. L&#39;extraction passe par l&#39;ordonnanceur, jamais par la requête de dépôt.</strong> La tâche <code>media_text_extraction</code> (portée organisation, toutes les 5 minutes, <code>app/media/indexing.py</code>) fonctionne ainsi :</p><ul><li><strong>Lot borné.</strong> Elle traite 25 documents par passage, avec un budget d&#39;une minute de lecture, et rattrape au plus 50 documents par passage pour les sites manquants.</li><li><strong>Lecture sans verrou, écriture courte.</strong> Elle lit et extrait sans verrou. Chaque média est ensuite verrouillé et relu juste avant l&#39;écriture : un média exclu ou supprimé pendant l&#39;extraction n&#39;est pas réindexé.</li><li><strong>États.</strong> <code>media_assets.extraction_status</code> vaut <code>pending</code>, <code>indexed</code>, <code>needs_engine</code> (le Core seul ne sait pas le lire, et aucun moteur n&#39;est branché), <code>empty</code> (tous les moteurs ont été essayés, sans texte) ou <code>failed</code> (3 échecs). Il vaut <code>NULL</code> pour une image ou un son. Les <code>needs_engine</code> sont repris une fois quand un moteur est branché.</li></ul><p><strong>6. Les bornes.</strong></p><ul><li>1 000 pages par PDF, 300 000 caractères de texte (un <code>tsvector</code> PostgreSQL ne dépasse pas 1 Mio), 30 secondes par extraction native, exécutée hors de la boucle (<code>asyncio.to_thread</code>).</li><li>La taille du fichier est opposée à <code>MEDIA_UPLOAD_MAX_MB</code> avant la lecture, puis au flux.</li><li><code>pypdf</code> limite lui-même chaque flux décompressé à 75 Mo.</li><li>Un PDF chiffré ou corrompu compte comme une tentative, jamais comme une panne du passage.</li></ul><p><strong>7. Tika suit le patron de ClamAV</strong> (ADR-0027, <code>app/media/tika.py</code>).</p><ul><li><strong>Réglages.</strong> <code>TIKA_URL</code> vide veut dire inactif : rien n&#39;est contacté. <code>TIKA_URL=http://tika:9998</code> active le service <code>tika</code> du compose (profil <code>extraction</code>, image <code>apache/tika:4.0.0-full</code>, aucun port publié). <code>TIKA_TIMEOUT_SECONDS</code> vaut 60 s par défaut, entre 5 et 120. Un réglage illisible refuse le démarrage.</li><li><strong>Appel.</strong> L&#39;adaptateur fait <code>PUT /tika</code>, avec <code>Accept: text/plain</code>, aucune redirection suivie et une réponse plafonnée à 2 Mio. Au-delà, le texte est <strong>tronqué</strong> : une panne ne compterait jamais de tentative et bloquerait la file.</li><li><strong>Verdicts.</strong> Un 200, même vide, est un verdict concluant (<code>empty</code> s&#39;il est vide). Un 422 (fichier chiffré ou illisible) compte une tentative. Injoignable, délai dépassé ou 5xx : le moteur est indisponible, aucune tentative n&#39;est comptée et le document reste en l&#39;état.</li><li><strong>Coupure du moteur pour le passage.</strong> Au premier moteur indisponible d&#39;un passage, le moteur n&#39;est plus appelé jusqu&#39;à la fin du passage. Le txt, le csv et les PDF texte continuent d&#39;être traités par le Core. Une ligne de journal technique est écrite par passage (<code>moteur_coupe</code> dans le compte-rendu).</li><li><strong>Recette réelle.</strong> L&#39;API de Tika 4.0.0 a été vérifiée contre le vrai conteneur : texte d&#39;un docx, 422 pour un PDF chiffré, corrompu ou vide, 200 vide pour des octets non reconnus, <code>GET /version</code> en texte brut. Un test d&#39;intégration facultatif (<code>TIKA_TEST_URL</code>) a passé contre lui.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Tika comme fournisseur du catalogue IA (<code>OcrPort</code>)</strong></td><td>Il aurait fallu une politique IA par organisation pour extraire du texte, et chaque extraction aurait compté dans le budget et le journal IA. Tika est un service local, pas un modèle. Décision du Product Owner.</td></tr><tr><td><strong>Tika seul, sans extraction native</strong></td><td>Chaque installation aurait eu un conteneur Java de plus pour lire des PDF qui portent déjà leur texte, c&#39;est-à-dire l&#39;essentiel des documents d&#39;une collectivité.</td></tr><tr><td><strong>Un fournisseur d&#39;OCR en ligne</strong> (Mistral OCR, Google Document AI, AWS Textract, Azure)</td><td>Les documents sortent de l&#39;infrastructure. Les services américains relèvent du Cloud Act. Le chemin IA existant reste disponible pour qui le choisit.</td></tr><tr><td><strong>Docling, docTR, PaddleOCR</strong></td><td>Meilleurs sur les mises en page complexes, mais ce sont des dépendances lourdes (modèles d&#39;apprentissage, GPU pour aller vite), disproportionnées pour un CMS de collectivité.</td></tr><tr><td><strong>N&#39;indexer que les documents cités par un contenu</strong></td><td>Plus juste sur le fond, mais il aurait fallu recalculer à chaque écriture de contenu, et la recherche des usages n&#39;est pas indexée (ADR-0041). Décision du Product Owner.</td></tr><tr><td><strong>Indexation explicite (opt-in)</strong></td><td>Un document oublié serait resté introuvable. Or les délibérations sont précisément ce qu&#39;on cherche sur le site d&#39;une collectivité.</td></tr><tr><td><strong>Une ligne d&#39;index par organisation (<code>site_id</code> nul)</strong></td><td>Elle aurait défait la garantie structurelle de l&#39;Epic E10 : <code>site_id</code> non nul, et toute recherche bornée à un site par construction.</td></tr><tr><td><strong>Extraire au dépôt</strong></td><td>Lire un PDF de 50 Mo, ou attendre un OCR, n&#39;a rien à faire dans le temps de réponse d&#39;un agent.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une délibération déposée en PDF est trouvable par son contenu dès le passage suivant, sur tous les sites de l&#39;organisation, sans rien déployer.</li><li>Un exploitant qui veut les scans et les fichiers Office démarre un conteneur et pose une variable. Rien ne change pour qui ne le fait pas.</li><li><code>search_index.document_id</code> a enfin sa clé étrangère : supprimer un média emporte ses lignes d&#39;index.</li><li>Tika en panne ne bloque ni la file ni les documents que le Core sait lire seul.</li></ul><p><strong>Négatives</strong></p><ul><li>Un document est public et, désormais, <strong>trouvable</strong>. Un brouillon déposé et non exclu apparaît dans la recherche du site. L&#39;écran le dit, mais c&#39;est une exposition nouvelle.</li><li>Le texte d&#39;un document est recopié dans chaque site de l&#39;organisation : l&#39;index grossit du nombre de sites.</li><li>Un document n&#39;a pas de date de publication : il se range en fin de tri par date et échappe à la facette de période.</li><li>Le surlignage de l&#39;extrait ne voit pas les mots accentués (<code>ts_headline</code> sans <code>unaccent</code>). C&#39;est un défaut antérieur, commun aux contenus.</li><li>Les documents extraits nativement ne sont pas vectorisés pour la recherche sémantique (RAG) du back-office.</li><li>Le budget d&#39;un passage n&#39;est vérifié qu&#39;entre deux documents : un document lent peut, à lui seul, le dépasser jusqu&#39;au délai de Tika.</li><li>Des octets que Tika ne reconnaît pas donnent <code>empty</code>, pas <code>failed</code>.</li><li>L&#39;image <code>apache/tika:4.0.0-full</code> pèse plusieurs centaines de mégaoctets.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Extraction native (<code>app/media/extraction.py</code>), cycle de vie et tâche <code>media_text_extraction</code> (<code>app/media/indexing.py</code>), migration <code>0035</code> (<code>searchable</code>, états, index <code>(document_id, site_id)</code>, clé étrangère), <code>document_path</code> dans les résultats, case d&#39;exclusion et statut sur la fiche média — recette <code>apps/api/tests/test_mediatheque_extraction.py</code>.</li><li>[x] Adaptateur Tika livré inactif (<code>app/media/tika.py</code>, <code>TIKA_URL</code>, <code>TIKA_TIMEOUT_SECONDS</code>, service <code>tika</code> du compose, profil <code>extraction</code>), coupure du moteur pour le passage — recette <code>apps/api/tests/test_extraction_tika.py</code>, test d&#39;intégration passé contre <code>apache/tika:4.0.0-full</code>.</li><li>[x] Donner une date aux documents dans l&#39;index (celle du dépôt, ou une date saisie sur la fiche média), pour le tri par date et la facette de période. — champ facultatif « Date du document » (<code>media_assets.document_date</code>, migration <code>0048</code>, qui date aussi les lignes déjà indexées de leur dépôt), <code>document_published_at</code> et <code>redate_media_in_search</code> (<code>app/media/indexing.py</code>), date future refusée (422 sur le champ) — recette <code>apps/api/tests/test_date_des_documents.py</code>.</li><li>[ ] Vectoriser les documents extraits nativement pour la recherche sémantique du back-office (RAG).</li></ul>',30)])])}const g=t(o,[["render",s]]);export{m as __pageData,g as default};
